import 'package:flutter/foundation.dart';import 'package:hive/hive.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:uuid/uuid.dart';import '../domain/models/poll.dart';final pollServiceProvider = Provider<PollService>((ref) => PollService());class PollService {  static const String _pollsBoxName = 'polls';  Box<String>? _pollsBox;  Future<void> initialize() async {    _pollsBox = await Hive.openBox<String>(_pollsBoxName);    debugPrint(        '[PollService] Initialized with ${_pollsBox?.length ?? 0} polls');  }  Future<Poll> createPoll({    required String question,    required List<String> optionTexts,    required String creatorId,    Duration expiresIn = const Duration(days: 7),    bool isAnonymous = false,    bool allowsMultiple = false,  }) async {    final id = const Uuid().v4();    final now = DateTime.now();    final options = optionTexts        .map((text) => PollOption(              id: const Uuid().v4(),              text: text,              voterIds: [],            ))        .toList();    final poll = Poll(      id: id,      question: question,      options: options,      creatorId: creatorId,      createdAt: now,      expiresAt: now.add(expiresIn),      isAnonymous: isAnonymous,      allowsMultiple: allowsMultiple,    );    await _pollsBox?.put(id, _encodePoll(poll));    debugPrint(        '[PollService] Created poll: $question with ${options.length} options');    return poll;  }  Future<void> vote(String pollId, String optionId, String userId) async {    final poll = getPoll(pollId);    if (poll == null || poll.isExpired) return;    if (poll.hasVoted(userId) && !poll.allowsMultiple) {      debugPrint('[PollService] User already voted (single vote mode)');      return;    }    final updatedOptions = poll.options.map((opt) {      if (opt.id == optionId) {        if (opt.voterIds.contains(userId)) return opt;        return opt.copyWith(voterIds: [...opt.voterIds, userId]);      }      if (!poll.allowsMultiple && opt.voterIds.contains(userId)) {        return opt.copyWith(          voterIds: opt.voterIds.where((id) => id != userId).toList(),        );      }      return opt;    }).toList();    final updatedPoll = poll.copyWith(options: updatedOptions);    await _pollsBox?.put(pollId, _encodePoll(updatedPoll));    debugPrint(        '[PollService] User $userId voted for option $optionId in poll $pollId');  }  Future<void> removeVote(String pollId, String optionId, String userId) async {    final poll = getPoll(pollId);    if (poll == null) return;    final updatedOptions = poll.options.map((opt) {      if (opt.id == optionId) {        return opt.copyWith(          voterIds: opt.voterIds.where((id) => id != userId).toList(),        );      }      return opt;    }).toList();    final updatedPoll = poll.copyWith(options: updatedOptions);    await _pollsBox?.put(pollId, _encodePoll(updatedPoll));    debugPrint(        '[PollService] User $userId removed vote from option $optionId in poll $pollId');  }  Poll? getPoll(String pollId) {    final encoded = _pollsBox?.get(pollId);    if (encoded == null) return null;    return _decodePoll(encoded);  }  List<Poll> getAllPolls() {    final polls = <Poll>[];    _pollsBox?.toMap().forEach((key, value) {      try {        final poll = _decodePoll(value);        if (poll != null) polls.add(poll);      } catch (e) {        debugPrint('[PollService] Error decoding poll: $e');      }    });    polls.sort((a, b) => b.createdAt.compareTo(a.createdAt));    return polls;  }  List<Poll> getActivePolls() {    return getAllPolls().where((p) => !p.isExpired).toList();  }  List<Poll> getExpiredPolls() {    return getAllPolls().where((p) => p.isExpired).toList();  }  List<Poll> getPollsByCreator(String creatorId) {    return getAllPolls().where((p) => p.creatorId == creatorId).toList();  }  Future<void> deletePoll(String pollId) async {    await _pollsBox?.delete(pollId);    debugPrint('[PollService] Deleted poll: $pollId');  }  Future<void> clearAll() async {    await _pollsBox?.clear();    debugPrint('[PollService] Cleared all polls');  }  String _encodePoll(Poll poll) {    return poll.toJson().entries.map((e) => '${e.key}=${e.value}').join('|');  }  Poll? _decodePoll(String encoded) {    try {      final Map<String, dynamic> map = {};      for (final pair in encoded.split('|')) {        final idx = pair.indexOf('=');        if (idx == -1) continue;        final key = pair.substring(0, idx);        final value = pair.substring(idx + 1);        if (value.startsWith('[') && value.endsWith(']')) {          map[key] = _parseList(value);        } else if (value == 'true') {          map[key] = true;        } else if (value == 'false') {          map[key] = false;        } else if (int.tryParse(value) != null) {          map[key] = int.parse(value);        } else {          map[key] = value;        }      }      return Poll.fromJson(map);    } catch (e) {      debugPrint('[PollService] Decode error: $e');      return null;    }  }  List<dynamic> _parseList(String value) {    if (value == '[]') return [];    final content = value.substring(1, value.length - 1);    if (content.isEmpty) return [];    return content.split(',').map((s) => s.trim()).toList();  }}